/// one it came from (see `crate::schema::inferences::sourcing_catalog_fragment`).
pub fn sourcing_curation_io() -> semio_framework_plugin::AppIo {
    semio_framework_plugin::AppIo {
        artifact_schema: SOURCING_CURATION_SCHEMA.into(),
